={
  "model": "claude-sonnet-4-5",
  "max_tokens": 4096,
  "messages": [
    {
      "role": "user",
      "content": [
        {
          "type": "document",
          "source": {
            "type": "base64",
            "media_type": "application/pdf",
            "data": "={{ $binary.data.data }}"
          }
        },
        {
          "type": "text",
          "text": "Du bekommst ein ausgefülltes Antragsformular der Stadt Würzburg (Altenhilfeplan Nr. 2, Antrag auf Zuschuss für Altentagesstätten). Das Formular kann maschinell ausgefüllt sein ODER handschriftlich. Extrahiere ALLE ausgefüllten Felder als striktes JSON nach folgendem Schema. Wenn ein Feld leer/nicht lesbar ist, setze null. Bei Beträgen: nur die Zahl als float (z.B. 1250.50), keine Währung, kein Tausender-Punkt. IBAN/BIC trimmen, ohne Leerzeichen. Antwort NUR als JSON-Objekt, keine Erklärung davor oder danach, kein Code-Fence.

Schema:
{
  "haushaltsjahr": integer | null,
  "name": string | null,                    // Name der Einrichtung
  "traeger": string | null,                 // Trägerverein/Organisation
  "strasse": string | null,
  "hausnummer": string | null,
  "plz": string | null,                      // 5-stellig
  "ort": string | null,
  "bankverbindung": string | null,           // Name der Bank, optional
  "iban": string | null,
  "bic": string | null,                      // nur wenn Nicht-DE-IBAN
  "ansprechpartner": string | null,
  "telefon": string | null,                  // optional
  "email": string | null,
  "betriebskosten_vorjahr_euro": float | null,
  "personalkosten_vorjahr_euro": float | null,
  "miete_jahr_euro": float | null,           // monatlich × 12 wenn monatlich angegeben
  "raeume_vorhanden": "ja" | "nein" | null,
  "raeume_unentgeltlich": "ja" | "nein" | null,
  "antragsdatum": string | null              // ISO YYYY-MM-DD
}"
        }
      ]
    }
  ]
}

parameters.jsCode:
// Parse Claude's JSON-Antwort (text content) und ergänze um Pflicht-Defaults.
const input = $input.first().json;
const content = input.content?.[0]?.text;
if (!content) {
  throw new Error('Claude lieferte keinen Text-Content zurück: ' + JSON.stringify(input));
}
let extr;
try {
  // Falls Claude doch ein Code-Fence schickt, abstreifen
  const cleaned = content.trim().replace(/^```json\n?/, '').replace(/\n?```$/, '');
  extr = JSON.parse(cleaned);
} catch (e) {
  throw new Error('Claude-Antwort ist kein JSON: ' + content.slice(0, 500));
}

// Defaults für UE0-Antragstellung
extr.submitted_language = 'de';
extr.submitted_at = new Date().toISOString();
extr.antragsdatum = extr.antragsdatum || new Date().toISOString().slice(0, 10);
extr.status = 'eingegangen';

// Bemessungs-Felder (Migration 029) bleiben null — Original-PDF fragt sie nicht ab
// geforderte_foerdersumme_euro bleibt null — Sachbearbeitung muss ergänzen

return [{ json: { extrahiert: extr, einreichung_id: $('Webhook Trigger (Supabase NOTIFY)').first().json.body.einreichung_id } }];
